[8385]={["atomIDs"]={"8385:description:9-82","8385:description:84-163","8385:objective:1-160"},["opening"]="The brigadier encouraged experienced fighters to keep moving between the fronts. Their example mattered to others in the field, and another set of the three battlegrounds' honors could attest that continued service.",["pending"]="{actor} planned to present another three Marks of Honor from each named battleground.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the three-battleground mark turn-in to an Alliance Brigadier General.",["sourceClassMask"]="?",["sourceHash"]="587e3fdca6f5af96f1d653716176743618ac87f9db6f6cbe4ffc9847cda6d1d3",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
