[8399]={["atomIDs"]={"8399:description:1-121","8399:description:124-216","8399:description:221-318","8399:description:321-402","8399:description:407-457","8399:description:460-476","8399:objective:1-96"},["opening"]="Astranaar depended on the forest's protection as well as its living beauty. The brigadier described Silverwing resistance as a defense against the possibility of a larger Horde advance.",["pending"]="{actor} would return three marks in support of Ashenvale's defense.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the marks to the Alliance brigadier general.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="e47326de0838b0010ec4b7dda809bb8d38bbc5d4fd95b8a09f0b4d4066889815",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8400]={["atomIDs"]={"8400:description:1-121","8400:description:124-216","8400:description:221-318","8400:description:321-402","8400:description:407-457","8400:description:460-476","8400:objective:1-96"},["opening"]="To the brigadier, the forest stood between Astranaar and the Barrens. Defending it in Warsong Gulch was therefore a military obligation as well as the Sentinels' cause.",["pending"]="{actor} planned to bring three Warsong marks for that defense.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the three marks to the Alliance.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="70fec8af39882bf3f2040eeb7a6e8f8aab137141758702b9f0634804a0f62175",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8401]={["atomIDs"]={"8401:description:1-121","8401:description:124-249","8401:description:254-351","8401:description:354-435","8401:description:438-484","8401:description:487-503","8401:objective:1-96"},["opening"]="The brigadier supported the Silverwings for reasons beyond their preservation of the trees. The forest could obstruct a large attack, and its loss would leave Astranaar vulnerable.",["pending"]="{actor} would carry three marks from the gulch to an Alliance brigadier.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered three Warsong marks to the brigadier.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="ad22c6440e7ab101a12d7ffbae62db7892e6dbfc722a46ea0c0524cc10791075",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8402]={["atomIDs"]={"8402:description:1-121","8402:description:124-216","8402:description:221-318","8402:description:321-402","8402:description:407-457","8402:description:460-476","8402:objective:1-96"},["opening"]="The destruction in Warsong threatened a natural defensive line. The brigadier called for aid before the loss of that barrier made Astranaar harder to hold.",["pending"]="{actor} would take three Warsong marks as proof of support.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the marks to an Alliance brigadier general.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="54c82d7e0692fce25753ba8199bacb55c1613f23ddf7028c2b6f7b351be06da0",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
