[8405]={["atomIDs"]={"8405:description:1-121","8405:description:123-215","8405:description:220-317","8405:description:319-400","8405:description:405-455","8405:description:457-473","8405:objective:1-96"},["opening"]="For the Alliance, aid in Warsong meant helping hold the wooded ground that shielded Astranaar. The brigadier's summons treated the Outriders' harvest as a strategic danger.",["pending"]="{actor} planned to carry three marks to an Alliance brigadier general.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the Warsong marks to the brigadier general.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="7b75cb6888a0df588ca24aa1bf75cbfbc94ac30f18276d76382de926828a760d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
